<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class StockMovement extends Model {protected $fillable=['inventory_product_id','type','quantity','stock_before','stock_after','unit_price','reference','reason','supplier_id','user_id']; protected $casts=['unit_price'=>'decimal:2']; public function product():BelongsTo{return $this->belongsTo(InventoryProduct::class,'inventory_product_id');} public function supplier():BelongsTo{return $this->belongsTo(Supplier::class);} public function user():BelongsTo{return $this->belongsTo(User::class);}}
